	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/telegram/start", wrapper.StartTelegramLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/telegram/verify", wrapper.VerifyTelegramLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/profile", wrapper.GetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/rulesets/{id}.srs", wrapper.GetRuleSet)
	})

	return r
